import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [viewStudents, setViewStudents] = useState(false);
  const [viewSupervisors, setViewSupervisors] = useState(false);
  const [viewEvaluators, setViewEvaluators] = useState(false);

  const [editingIndex, setEditingIndex] = useState(null);
  const [editingType, setEditingType] = useState("");
  const [editingUserId, setEditingUserId] = useState(null);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    const { data: users } = await axios.get("http://localhost:5000/api/user");
    const { data: studentsData } = await axios.get("http://localhost:5000/api/student");
    const { data: supervisorsData } = await axios.get("http://localhost:5000/api/facultyAdvisor");
    const { data: evaluatorsData } = await axios.get("http://localhost:5000/api/evaluator");

    const studentList = users
      .filter((u) => u.role === "Student")
      .map((u) => {
        const studentInfo = studentsData.find((s) => s.userId === u._id);
        return {
          userId: u._id,
          name: studentInfo?.studentName || "",
          email: u.email,
          role: u.role,
          registrationNumber: studentInfo?.regNo || "",
          password: u.password,
        };
      });

    const supervisorList = users
      .filter((u) => u.role === "Supervisor")
      .map((u) => {
        const info = supervisorsData.find((s) => s.userId === u._id);
        return {
          userId: u._id,
          name: info?.name || "",
          email: u.email,
          role: u.role,
          password: u.password,
        };
      });

    const evaluatorList = users
      .filter((u) => u.role === "Evaluator")
      .map((u) => {
        const info = evaluatorsData.find((e) => e.userId === u._id);
        return {
          userId: u._id,
          name: info?.name || "",
          email: u.email,
          role: u.role,
          password: u.password,
        };
      });

    setStudents(studentList);
    setSupervisors(supervisorList);
    setEvaluators(evaluatorList);
    setViewStudents(true);
    setViewSupervisors(true);
    setViewEvaluators(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (editingIndex !== null) {
      await handleUpdateUser();
      return;
    }

    const userRes = await axios.post("http://localhost:5000/api/user", {
      username: name,
      email,
      password,
      role,
    });

    const user = userRes.data;

    if (role === "Student") {
      await axios.post("http://localhost:5000/api/student", {
        userId: user._id,
        studentName: name,
        regNo: registrationNumber,
        isGrouped: false,
      });
    } else if (role === "Supervisor") {
      await axios.post("http://localhost:5000/api/facultyAdvisor", {
        userId: user._id,
        name,
      });
    } else if (role === "Evaluator") {
      await axios.post("http://localhost:5000/api/evaluator", {
        userId: user._id,
        name,
      });
    }

    await fetchUsers();
    clearForm();
  };

  const handleUpdateUser = async () => {
    const getUserFromIndex = () => {
      if (editingType === "student") {
        return students[editingIndex];
      } else if (editingType === "supervisor") {
        return supervisors[editingIndex];
      } else if (editingType === "evaluator") {
        return evaluators[editingIndex];
      }
      return null;
    };

    const userToUpdate = getUserFromIndex();
    if (!userToUpdate) return;

    await axios.patch(`http://localhost:5000/api/user/${editingUserId}`, {
      username: name,
      email,
      password,
      role,
    });

    if (editingType === "student") {
      await axios.patch(`http://localhost:5000/api/student/${userToUpdate.userId}`, {
        studentName: name,
        regNo: registrationNumber,
      });
    } else if (editingType === "supervisor") {
      await axios.patch(`http://localhost:5000/api/facultyAdvisor/${userToUpdate.userId}`, {
        name,
      });
    } else if (editingType === "evaluator") {
      await axios.patch(`http://localhost:5000/api/evaluator/${userToUpdate.userId}`, {
        name,
      });
    }

    await fetchUsers();
    clearForm();
  };

  const handleDelete = async (userId, type) => {
    await axios.delete(`http://localhost:5000/api/user/${userId}`);

    if (type === "student") {
      await axios.delete(`http://localhost:5000/api/student/${userId}`);
    } else if (type === "supervisor") {
      await axios.delete(`http://localhost:5000/api/facultyAdvisor/${userId}`);
    } else if (type === "evaluator") {
      await axios.delete(`http://localhost:5000/api/evaluator/${userId}`);
    }

    await fetchUsers();
  };

  const handleEdit = (index, type) => {
    setEditingIndex(index);
    setEditingType(type);
    let user;
    if (type === "student") {
      user = students[index];
    } else if (type === "supervisor") {
      user = supervisors[index];
    } else {
      user = evaluators[index];
    }

    setEditingUserId(user.userId);
    setName(user.name);
    setEmail(user.email);
    setRole(user.role);
    setRegistrationNumber(user.registrationNumber || "");
    setPassword(user.password || "");
  };

  const handleResetPassword = async (userId) => {
    const newPassword = prompt("Enter new password:");
    if (!newPassword) return;

    await axios.patch(`http://localhost:5000/api/user/${userId}`, {
      password: newPassword,
    });

    alert("Password updated successfully.");
    await fetchUsers();
  };

  const clearForm = () => {
    setName("");
    setEmail("");
    setRole("");
    setRegistrationNumber("");
    setPassword("");
    setEditingIndex(null);
    setEditingType("");
    setEditingUserId(null);
  };

  const renderTable = (data, type) => (
    <div className={`${type}-table`}>
      <h2>{type.charAt(0).toUpperCase() + type.slice(1)} List</h2>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Role</th>
            {type === "student" && <th>Registration Number</th>}
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {data.map((user, index) => (
            <tr key={index}>
              <td>{user.name}</td>
              <td>{user.email}</td>
              <td>{user.role}</td>
              {type === "student" && <td>{user.registrationNumber}</td>}
              <td>
                <button onClick={() => handleEdit(index, type)}>Edit</button>
                <button onClick={() => handleResetPassword(user.userId)}>
                  Reset Password
                </button>
                <button onClick={() => handleDelete(user.userId, type)}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <form onSubmit={handleSubmit} className="user-form">
            <label>Name</label>
            <input value={name} onChange={(e) => setName(e.target.value)} required />

            <label>Email</label>
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />

            <label>Password</label>
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required />

            <label>Role</label>
            <select value={role} onChange={(e) => setRole(e.target.value)} required>
              <option value="">Select Role</option>
              <option value="Student">Student</option>
              <option value="Supervisor">Supervisor</option>
              <option value="Evaluator">Evaluator</option>
            </select>

            {role === "Student" && (
              <>
                <label>Registration Number</label>
                <input value={registrationNumber} onChange={(e) => setRegistrationNumber(e.target.value)} required />
              </>
            )}

            {role === "Evaluator" && (
              <>
                <label>Registration Number</label>
                <input disabled placeholder="Not applicable" />
              </>
            )}

            <button type="submit">{editingIndex !== null ? "Update" : "Submit"}</button>
          </form>

          {viewStudents && renderTable(students, "student")}
          {viewSupervisors && renderTable(supervisors, "supervisor")}
          {viewEvaluators && renderTable(evaluators, "evaluator")}
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
